using System;
using System.ComponentModel.DataAnnotations;

public class FutureDateAttribute : ValidationAttribute
{
    protected override ValidationResult IsValid(object value, ValidationContext context)
    {
        if (value is DateTime date)
        {
            if (date > DateTime.UtcNow)
            {
                return ValidationResult.Success;
            }
            return new ValidationResult(
                ErrorMessage ?? "The date must be in the future.");
        }

        return new ValidationResult("Invalid date value.");
    }
}

// Usage
public class EventViewModel
{
    public string Title { get; set; }

    [FutureDate(ErrorMessage = "Please choose a date after today.")]
    public DateTime EventDate { get; set;;
}

[HttpPost]
public IActionResult Create(EventViewModel model)
{
    if (!ModelState.IsValid) return View(model);
    return RedirectToAction("Details", new { id = model.Id });
}

using System;
using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;

public class BookingViewModel : IValidatableObject
{
    [Required]
    public DateTime StartDate { get; set; }

    [Required]
    public DateTime EndDate { get; set; }

    public IEnumerable<ValidationResult> Validate(ValidationContext context)
    {
        if (EndDate <= StartDate)
        {
            yield return new ValidationResult(
                "End date must be after the start date.",
                new[] { nameof(EndDate) });
        }

        var nights = (EndDate - StartDate).TotalDays;
        if (nights > 30)
        {
            yield return new ValidationResult(
                "Bookings cannot exceed 30 nights.",
                new[] { nameof(EndDate) });
        }
    }
}
